style.label:
 for the hidden checkbox above it, so a
   click anywhere ticks the box and the rules below let the page through. A CSS animation does the
   same thing on its own after six seconds. That matters because a frame sandboxed without
   "allow-scripts" blocks every  and every inline onload= / onclick= as well. */

.gate-open {
  position: absolute;
  top: 0;
  left: 0;
  width: 1px;
  height: 1px;
  margin: 0;
  opacity: 0;
  pointer-events: none;
}

svg.gated { overflow: hidden; background: #fff; }

.gate {
  position: fixed;
  inset: 0;
  z-index: 2000;
  overflow-x: hidden;
  overflow-y: auto;
  background: #fff;
  color: #393939;
  color-scheme: light;
  scrollbar-color: auto;
  cursor: default;
  font: 400 16px/1.5 "Rubik", "Source Sans Pro", "Segoe UI", Arial, sans-serif;
  transition: opacity .32s ease, visibility 0s linear .32s;
  animation: gate-auto-out .32s ease 6.3s forwards;
}
/* plain grey scrollbar, so it does not give the gold theme away */
.gate::-webkit-scrollbar { width: 15px; height: 15px; }
.gate::-webkit-scrollbar-track { background: #f1f1f1; }
.gate::-webkit-scrollbar-thumb { background: #c1c1c1; border: 0; border-radius: 0; }

/* gone: ticked box, timed-out animation, or the script adding .gate-out */
.gate-open:checked ~ .gate,
.gate.gate-out {
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
}

@keyframes gate-auto-out { to { opacity: 0; visibility: hidden; pointer-events: none; } }

svg:not(.gated) .gate { display: none; } /* e.g. pyrite embedded in the about:blank shield tab */

.gate *, .gate *::before, .gate *::after { box-sizing: border-box; }
.gate a { color: inherit; text-decoration: none; cursor: pointer; }
.gate-wrap { width: min(100% - 48px, 1200px); margin: 0 auto; }

/* header */
.gate-head { background: #00303c; color: #fff; }
.gate-top { display: flex; align-items: center; justify-content: space-between; gap: 24px; min-height: 98px; }
.gate-brand { font-size: 24px; letter-spacing: .1px; }
.gate-tools { display: flex; align-items: center; gap: 28px; }
.gate-contact { font-size: 13px; text-decoration: underline !important; }
.gate-search { display: flex; width: 224px; height: 40px; }
.gate-input { flex: 1; display: flex; align-items: center; padding: 0 14px; border-radius: 3px 0 0 3px; background: #ececec; color: #666; font-size: 14px; }
.gate-sbtn { display: grid; place-items: center; width: 40px; border-radius: 0 3px 3px 0; background: #0f7b80; color: #fff; }
.gate-sbtn svg { width: 18px; height: 18px; }

/* nav */
.gate-nav { background: #076369; }
.gate-nav .gate-wrap { display: flex; justify-content: space-between; }
.gate-nav a { display: flex; align-items: center; gap: 8px; height: 50px; padding: 0 20px; color: #fff; font-size: 14.5px; font-weight: 500; white-space: nowrap; }
.gate-nav a:hover { background: #0a7a81; }
.gate-nav svg { width: 10px; height: 10px; }

/* hero + cards */
.gate-hero { background: linear-gradient(#002029 35%, #076369 132%); color: #fff; padding-top: 58px; }
.gate-hero h1 { margin: 0; max-width: 640px; padding-bottom: 130px; font-size: 56px; font-weight: 300; line-height: 70px; }

.gate-cards { position: relative; display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; margin-top: -64px; }
.gate-card { display: flex; flex-direction: column; background: #fff; box-shadow: 0 2px 10px rgba(0, 0, 0, .2); }
.gate-photo { position: relative; aspect-ratio: 4 / 3; overflow: hidden; }
/* photos come from ed.gov; no onload= needed, a broken one just lets the colour block show */
.gate-photo img, .gate-sq img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
.gate-photo.p1 { background: radial-gradient(60% 70% at 30% 30%, rgba(255,255,255,.35), transparent 70%), linear-gradient(160deg, #cbd8da, #8ea6ab 55%, #5d7a80); }
.gate-photo.p2 { background: radial-gradient(60% 70% at 70% 35%, rgba(255,255,255,.3), transparent 70%), linear-gradient(160deg, #dccdbd, #a68e74 55%, #6e5a47); }
.gate-photo.p3 { background: radial-gradient(60% 70% at 40% 30%, rgba(255,255,255,.3), transparent 70%), linear-gradient(160deg, #bccadb, #7f95b2 55%, #4d6385); }
.gate-body { display: flex; flex: 1; flex-direction: column; align-items: flex-start; padding: 22px 24px 28px; }
.gate-body h2 { margin: 0 0 10px; color: #00303c; font-size: 24px; font-weight: 500; line-height: 1.25; }
.gate-body p { margin: 0 0 20px; }
.gate-btn { margin-top: auto; padding: 11px 20px; border-radius: 4px; background: #005ea2; color: #fff; font-weight: 500; }
.gate-btn:hover { background: #1a4480; }

/* higher education tiles */
.gate-higher { padding: 72px 0 8px; }
.gate-eyebrow { margin: 0 0 6px; color: #076369; font-size: 13px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; }
.gate-higher h2 { margin: 0 0 10px; color: #00303c; font-size: 32px; font-weight: 500; line-height: 1.2; }
.gate-lede { margin: 0 0 28px; max-width: 640px; }
.gate-tiles { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; }
.gate-tile { display: flex; flex-direction: column; }
.gate-sq { position: relative; aspect-ratio: 1; overflow: hidden; margin-bottom: 14px; }
.gate-sq.q1 { background: linear-gradient(160deg, #cfd9c5, #8aa383); }
.gate-sq.q2 { background: linear-gradient(160deg, #cbd3dd, #8393a8); }
.gate-sq.q3 { background: linear-gradient(160deg, #d9d0bf, #a39076); }
.gate-sq.q4 { background: linear-gradient(160deg, #bfd3d6, #7ea1a6); }
.gate-tile strong { color: #00303c; font-size: 20px; font-weight: 500; line-height: 1.25; }
.gate-tile span { margin-top: 4px; color: #005ea2; text-decoration: underline; }

.gate-ferpa { padding: 56px 0 0; }
.gate-ferpa h2 { margin: 0 0 10px; color: #00303c; font-size: 26px; font-weight: 500; line-height: 1.25; }
.gate-ferpa p { max-width: 640px; margin: 0 0 18px; }
.gate-ferpa .gate-btn { display: inline-block; }

/* sections */
.gate-section { padding: 64px 0 8px; }
.gate-grid3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 48px; }
.gate-section h2 { margin: 0 0 12px; color: #00303c; font-size: 26px; font-weight: 500; line-height: 1.25; }
.gate-section p { margin: 0 0 14px; }
.gate-links a { display: block; padding: 3px 0; color: #005ea2; text-decoration: underline; }
.gate-links a:hover { color: #1a4480; }

/* footer */
.gate-foot { margin-top: 72px; padding: 44px 0 64px; background: #00303c; color: #fff; }
.gate-foot .gate-wrap { display: grid; grid-template-columns: 1fr 2fr; gap: 40px; }
.gate-foot-brand { font-size: 22px; }
.gate-foot-links { display: grid; grid-template-columns: repeat(3, auto); gap: 10px 36px; align-content: start; font-size: 14px; }
.gate-foot a { text-decoration: underline; }

.gate-help { position: fixed; right: 18px; bottom: 18px; z-index: 2; padding: 12px 16px; border-radius: 4px; background: #005ea2; color: #fff; font-size: 14px; font-weight: 700; box-shadow: 0 2px 8px rgba(0, 0, 0, .35); }

@media (max-width: 900px) {
  .gate-top { min-height: 74px; }
  .gate-brand { font-size: 19px; }
  .gate-search { display: none; }
  .gate-nav .gate-wrap { overflow: hidden; justify-content: flex-start; }
  .gate-nav a { padding: 0 14px; }
  .gate-hero { padding-top: 40px; }
  .gate-hero h1 { padding-bottom: 110px; font-size: 34px; line-height: 42px; }
  .gate-cards { grid-template-columns: 1fr; margin-top: -56px; }
  .gate-tiles { grid-template-columns: 1fr 1fr; gap: 20px; }
  .gate-grid3 { grid-template-columns: 1fr; gap: 36px; }
  .gate-foot .gate-wrap { grid-template-columns: 1fr; }
  .gate-foot-links { grid-template-columns: 1fr 1fr; }
}

/* nudge, in the corner of the cover page */
.gate-hint {
  position: fixed;
  left: 50%;
  bottom: 18px;
  z-index: 3;
  transform: translateX(-50%);
  padding: 10px 18px;
  border-radius: 999px;
  background: #005ea2;
  color: #fff;
  font-size: 14px;
  font-weight: 500;
  white-space: nowrap;
  box-shadow: 0 2px 8px rgba(0, 0, 0, .35);
  pointer-events: none;
}
.gate-hint b { font-weight: 700; font-variant-numeric: tabular-nums; }

@media (max-width: 620px) {
  .gate-hint { bottom: 64px; font-size: 13px; padding: 9px 14px; }
}

body.script:
//
(() => {
  "use strict";

  const BATCH = 60;       // cards added per step after a search or a reshuffle
  const LOOKAHEAD = 1400; // px of cards to keep ready below the fold

  // where the game folders live (see config.js)
  const BASE = ((window.PYRITE && window.PYRITE.gamesBase) || "games/").replace(/\/*$/, "/");

  // These pages break out of frames or refuse to run inside one, so they open in their own tab.
  const NOFRAME = new Set([
    "selenite/cuttherope-holiday", "selenite/madalincars",
    "selenite/motox3m", "selenite/motox3m-pool", "selenite/motox3m-spooky", "selenite/motox3m-winter",
    "gn-math/316", "gn-math/263",
  ]);

  // ~80 of the emulator pages call this on whichever page frames them
  window.maeExportApis_ = () => {};

  const $ = (id) => document.getElementById(id);

  // The root of this document is an <svg>, so document.createElement() would return
  // elements in no namespace at all: an "a" that is not a link, an "iframe" with no
  // browsing context, and .href / .src as plain expando properties. Create them in the
  // XHTML namespace instead (which is also correct in a plain .html page).
  const XHTML = "http://www.w3.org/1999/xhtml";
  const el = (name) => document.createElementNS(XHTML, name);

  const grid = $("grid");
  const sentinel = $("sentinel");
  const glow = $("glow");
  const mark = $("wordmark");
  const input = $("q");
  const clearBtn = $("clear");
  const count = $("count");
  const empty = $("empty");
  const sortBox = document.querySelector(".sort");
  const sortBtns = [...sortBox.querySelectorAll("[data-sort]")];
  const gilt = [...document.querySelectorAll(".gilt")];

  // the <svg> element: documentElement when this file is opened as .svg, found by namespace
  // when the very same markup is inline SVG inside an .html page. getElementsByTagNameNS is
  // used instead of "svg:has(foreignObject)" because :has() throws a SyntaxError while parsing
  // the selector on engines that do not know it — which took this whole script down with it.
  const SVG_NS = "http://www.w3.org/2000/svg";
  const root = document.documentElement.localName === "svg"
    ? document.documentElement
    : (document.getElementsByTagNameNS(SVG_NS, "svg")[0] || document.documentElement);

  // the cover page is up for exactly as long as its element is in the document
  const gated = () => !!document.getElementById("gate");
  const still = matchMedia("(prefers-reduced-motion: reduce)").matches;
  const clamp = (v, lo, hi) => Math.min(hi, Math.max(lo, v));

  /* ---------- data, search, sort ---------- */

  // lowercase, drop accents/punctuation so "funkin'" or "pokemon" still find "Funkin’" / "Pokémon"
  const norm = (s) => s.normalize("NFKD").replace(/[̀-ͯ]/g, "").toLowerCase()
    .replace(/[^\p{L}\p{N}]+/gu, " ").trim();

  const collator = new Intl.Collator("en", { numeric: true, sensitivity: "base" });
  const alpha = GAMES
    .map((g) => ({ ...g, key: norm(g.name) }))
    .sort((a, b) => collator.compare(a.name, b.name));
  const byId = new Map(alpha.map((g) => [g.id, g]));

  let shuffled = alpha;
  let mode = "az";
  let shown = alpha;
  let next = 0;

  function reshuffle() {
    const a = alpha.slice();
    for (let i = a.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [a[i], a[j]] = [a[j], a[i]];
    }
    shuffled = a;
  }

  const fmt = (n) => n.toLocaleString("en-US");

  /* ---------- cards ---------- */

  // ids and image paths can hold subfolders, spaces and emoji
  const enc = (p) => p.split("/").map(encodeURIComponent).join("/");
  const gameDir = (g) => BASE + enc(g.id) + "/";
  const gameUrl = (g) => gameDir(g) + "index.html";

  // favicon-sized art looks soft stretched across a whole tile, so flag it for the icon plate
  function watch(a, img) {
    const tiny = () => {
      if (img.naturalWidth && Math.min(img.naturalWidth, img.naturalHeight) < 130) a.classList.add("icon");
    };
    const gone = () => a.classList.add("missing");
    img.addEventListener("load", tiny, { once: true });
    img.addEventListener("error", gone, { once: true });
    if (img.complete) (img.naturalWidth ? tiny() : gone()); // already settled before we got here
  }

  // a card is a plain link to the game; the click handler below turns it into the in-page
  // player when scripts run, and does nothing when they do not
  function card(game, i) {
    const a = el("a");
    a.className = "card";
    a.dataset.id = game.id;
    a.href = gameUrl(game);
    if (NOFRAME.has(game.id)) { a.target = "_blank"; a.rel = "noopener"; }
    a.style.setProperty("--d", (i % 12) * 28 + "ms");

    const img = new Image();
    img.alt = "";
    img.decoding = "async";
    img.loading = "lazy";
    img.draggable = false;
    watch(a, img);
    img.src = gameDir(game) + enc(game.img);

    const mono = el("span");
    mono.className = "mono";
    mono.setAttribute("aria-hidden", "true");
    mono.textContent = (game.name.trim()[0] || "?");

    const name = el("div");
    name.className = "name";
    const label = el("span");
    label.textContent = game.name;
    name.appendChild(label);

    a.append(img, mono, name);
    return a;
  }

  // the markup ships with every card already in it, so the grid works with no script at all.
  // Rather than throw those nodes away and rebuild them (which would reload every image), adopt
  // them: re-tag the eight frameless ones, wire the art, and re-order into A–Z.
  function adopt() {
    const found = new Map();
    for (const a of grid.querySelectorAll("a.card[data-id]")) found.set(a.dataset.id, a);
    if (found.size !== alpha.length) return false; // markup and data disagree: just rebuild

    for (const g of alpha) {
      const a = found.get(g.id);
      if (NOFRAME.has(g.id)) { a.target = "_blank"; a.rel = "noopener"; }
      else { a.removeAttribute("target"); a.removeAttribute("rel"); }
      const img = a.querySelector("img");
      if (img) watch(a, img);
    }
    // re-append in A–Z order: moving a node keeps its loaded image
    grid.append(...alpha.map((g) => found.get(g.id)));
    alpha.forEach((g, i) => found.get(g.id).style.setProperty("--d", (i % 12) * 28 + "ms"));
    return true;
  }

  function more() {
    const end = Math.min(next + BATCH, shown.length);
    const frag = document.createDocumentFragment();
    for (let i = next; i < end; i++) frag.appendChild(card(shown[i], i - next));
    next = end;
    grid.appendChild(frag);
  }

  function fill() {
    while (next < shown.length && sentinel.getBoundingClientRect().top < innerHeight + LOOKAHEAD) more();
  }

  // once everything is rendered `fill` returns before touching layout, so this stays cheap.
  // capture: true because the scroller is .scroll, and scroll events do not bubble.
  addEventListener("scroll", fill, { passive: true, capture: true });
  addEventListener("resize", fill);

  /* ---------- the grid is a list of links first, a player trigger second ---------- */

  grid.addEventListener("click", (e) => {
    const a = e.target.closest("a.card");
    if (!a || !a.dataset.id) return;
    if (NOFRAME.has(a.dataset.id)) return;               // let it open its own tab
    if (e.metaKey || e.ctrlKey || e.shiftKey || e.altKey || e.button !== 0) return; // ditto
    e.preventDefault();
    location.hash = "#/" + enc(a.dataset.id);            // route() below opens the player
  });

  /* ---------- search + sort ---------- */

  const searchBox = input.closest(".search");

  function apply() {
    const terms = norm(input.value).split(" ").filter(Boolean);
    const base = mode === "az" ? alpha : shuffled;
    shown = terms.length ? base.filter((g) => terms.every((t) => g.key.includes(t))) : base;

    empty.hidden = shown.length > 0;
    count.textContent = countText();

    if (!terms.length && mode === "az" && adopt()) {     // first run: keep the shipped cards
      next = shown.length;
      return;
    }
    grid.replaceChildren();
    next = 0;
    fill();
  }

  const countText = () => (norm(input.value)
    ? fmt(shown.length) + " of " + fmt(alpha.length)
    : fmt(alpha.length) + " projects");

  // a short message in the count line, then back to the count
  let flashTimer = 0;
  function flash(msg) {
    clearTimeout(flashTimer);
    count.textContent = msg;
    flashTimer = setTimeout(() => { count.textContent = countText(); }, 3500);
  }

  input.addEventListener("input", () => {
    searchBox.classList.toggle("has-value", input.value !== "");
    apply();
  });

  function clearSearch() {
    input.value = "";
    searchBox.classList.remove("has-value");
    apply();
  }
  clearBtn.addEventListener("click", () => { clearSearch(); input.focus(); });

  input.addEventListener("keydown", (e) => {
    if (e.key === "Escape") { input.value ? clearSearch() : input.blur(); }
    else if (e.key === "Enter") input.blur(); // dismisses the phone keyboard
  });

  // "/" jumps to the search box
  addEventListener("keydown", (e) => {
    if (e.key !== "/" || e.ctrlKey || e.metaKey || e.altKey || current || gated()) return;
    if (/^(INPUT|TEXTAREA|SELECT)$/.test(document.activeElement.tagName)) return;
    e.preventDefault();
    input.focus();
    input.select();
  });

  let rolls = 0;
  sortBox.addEventListener("click", (e) => {
    const btn = e.target.closest("[data-sort]");
    if (!btn) return;
    const choice = btn.dataset.sort;
    if (choice === "random") {
      reshuffle(); // clicking Shuffle again deals a fresh order
      sortBox.style.setProperty("--rot", ++rolls * 360 + "deg");
    }
    mode = choice;
    sortBtns.forEach((b) => b.setAttribute("aria-pressed", String(b === btn)));
    sortBox.style.setProperty("--shift", mode === "az" ? "0%" : "100%");
    apply();
  });

  /* ---------- in-page player ---------- */

  const player = $("player");
  const pFrame = $("p-frame");
  const pTitle = $("p-title");
  const pIcon = $("p-icon");
  const pNewTab = $("p-newtab");
  const pFull = $("p-full");
  const pClose = $("p-close");
  const pUnfull = $("p-unfull");
  const pLoading = $("p-loading");
  const home = [document.querySelector(".top"), document.querySelector("main")];

  let current = null;   // game being played
  let frameEl = null;   // its <iframe>
  let lastFocus = null; // card to hand focus back to
  let inApp = false;    // true once we have navigated inside the page, so "back" lands on the grid
  let loadTimer = 0;
  let lastFs = 0;

  const fsActive = () => document.fullscreenElement || document.webkitFullscreenElement;

  function teardown() {
    clearTimeout(loadTimer);
    if (!frameEl) return;
    frameEl.src = "about:blank"; // silences audio right away
    frameEl.remove();
    frameEl = null;
  }

  function open(game) {
    if (current === game) return;
    teardown();
    current = game;
    if (!lastFocus) lastFocus = document.activeElement;

    pTitle.textContent = game.name;
    pNewTab.href = gameUrl(game);
    pIcon.hidden = true;
    pIcon.onload = () => { pIcon.hidden = false; };
    pIcon.onerror = () => { pIcon.hidden = true; };
    pIcon.src = gameDir(game) + enc(game.img);

    player.classList.remove("theater", "is-full");
    pLoading.classList.remove("done");
    player.hidden = false;
    // the page keeps its scrollbar gutter while locked; mirror it on the left so the player stays centred
    root.style.setProperty("--sbw", Math.max(0, innerWidth - root.clientWidth) + "px");
    root.classList.add("playing");
    home.forEach((el2) => { el2.inert = true; });

    frameEl = el("iframe");
    frameEl.title = game.name;
    frameEl.setAttribute("allow", "autoplay; fullscreen; gamepad; clipboard-write; accelerometer; gyroscope; microphone; camera");
    frameEl.setAttribute("allowfullscreen", "");
    const reveal = () => { pLoading.classList.add("done"); };
    frameEl.addEventListener("load", () => { reveal(); if (frameEl) frameEl.focus(); });
    loadTimer = setTimeout(reveal, 10000); // some games never fire `load`; don't hide them forever
    frameEl.src = gameUrl(game);
    pFrame.appendChild(frameEl);
    frameEl.focus();
  }

  function close() {
    if (!current) return;
    if (fsActive()) (document.exitFullscreen || document.webkitExitFullscreen).call(document);
    teardown();
    current = null;
    player.hidden = true;
    player.classList.remove("theater", "is-full");
    root.classList.remove("playing");
    home.forEach((el2) => { el2.inert = false; });
    if (lastFocus && lastFocus.focus) lastFocus.focus({ preventScroll: true });
    lastFocus = null;
    kick(); // restart the cursor-light loop
  }

  // "#/html/0-fa" -> that game
  function route() {
    if (gated()) return; // nothing opens behind the cover page
    const m = location.hash.match(/^#\/(.+)$/);
    let game = null;
    if (m) {
      try { game = byId.get(m[1].split("/").map(decodeURIComponent).join("/")); } catch (_) { /* bad escape */ }
    }
    if (game && !NOFRAME.has(game.id)) { open(game); return; }
    if (m) history.replaceState(null, "", location.pathname + location.search); // unknown id: tidy the URL
    close();
  }

  // x button / Esc: go back to the grid. After in-page navigation that is just "back",
  // so the browser history stays tidy; for a direct link we replace the entry instead.
  function leave() {
    if (inApp) history.back();
    else {
      history.replaceState(null, "", location.pathname + location.search);
      route();
    }
  }

  function toggleFull() {
    if (fsActive()) { (document.exitFullscreen || document.webkitExitFullscreen).call(document); return; }
    if (player.classList.contains("theater")) { player.classList.remove("theater"); return; }
    const req = pFrame.requestFullscreen || pFrame.webkitRequestFullscreen;
    if (!req) { player.classList.add("theater"); return; } // e.g. iPhone
    const r = req.call(pFrame);
    if (r && r.catch) r.catch(() => player.classList.add("theater"));
    // if the browser neither goes fullscreen nor refuses, don't leave the button looking dead
    setTimeout(() => { if (current && !fsActive()) player.classList.add("theater"); }, 900);
  }

  const onFullChange = () => {
    lastFs = performance.now();
    player.classList.toggle("is-full", !!fsActive());
    if (frameEl) frameEl.focus();
  };
  document.addEventListener("fullscreenchange", onFullChange);
  document.addEventListener("webkitfullscreenchange", onFullChange);

  pClose.addEventListener("click", leave);
  pFull.addEventListener("click", toggleFull);
  pUnfull.addEventListener("click", () => player.classList.remove("theater"));
  // the game keeps running in the frame, so once it is popped out we head back to the grid
  pNewTab.addEventListener("click", () => setTimeout(leave, 0));

  addEventListener("keydown", (e) => {
    if (e.key !== "Escape" || !current) return;
    if (fsActive() || performance.now() - lastFs < 400) return; // that Esc belongs to fullscreen
    if (player.classList.contains("theater")) { player.classList.remove("theater"); return; }
    leave();
  });

  addEventListener("hashchange", () => { inApp = true; route(); });

  /* ---------- light that follows the cursor ---------- */

  const hoverCard = (e) => {
    const c = e.target.closest(".card");
    if (!c) return;
    const r = c.getBoundingClientRect();
    c.style.setProperty("--mx", e.clientX - r.left + "px");
    c.style.setProperty("--my", e.clientY - r.top + "px");
  };
  grid.addEventListener("pointermove", hoverCard, { passive: true });

  let ptr = null; // pointer position while it is over the page
  const track = (e) => { ptr = { x: e.clientX, y: e.clientY }; };
  addEventListener("pointermove", track, { passive: true });
  addEventListener("pointerdown", track, { passive: true });
  addEventListener("pointercancel", () => { ptr = null; });
  addEventListener("pointerup", (e) => { if (e.pointerType !== "mouse") ptr = null; });
  root.addEventListener("pointerleave", () => { ptr = null; });

  const t0 = performance.now();
  let raf = 0;
  let last = t0;
  let p = 0, hi = 0, hx = 0, hy = 0; // gold band offset, hotspot strength, hotspot position
  let hot = false, lit = false;

  function frame(now) {
    raf = 0;
    if (current) return; // a game is running: leave the CPU to it (close() restarts this)

    const dt = Math.min(0.05, (now - last) / 1000);
    last = now;
    const k = still ? 1 : 1 - Math.exp(-dt * 9);

    // with no pointer the bands drift on their own, the way the old timed sweep did
    let tp = still ? 0.3 : 0.5 - 0.5 * Math.cos(((now - t0) / 1000) * Math.PI * 2 / 18);
    let th = 0, tx = hx, ty = hy;

    const r = mark.getBoundingClientRect();
    if (ptr) {
      tp = clamp(ptr.x / innerWidth, 0, 1);
      const dx = Math.max(r.left - ptr.x, 0, ptr.x - r.right);
      const dy = Math.max(r.top - ptr.y, 0, ptr.y - r.bottom);
      th = 0.3 + 0.7 * clamp(1 - Math.hypot(dx, dy) / (innerHeight * 0.6), 0, 1);
      tx = clamp(ptr.x - r.left, -0.15 * r.width, 1.15 * r.width);
      ty = clamp(ptr.y - r.top, -0.2 * r.height, 1.2 * r.height);
      if (!hot) { hx = tx; hy = ty; } // first touch of the page: appear under the cursor, don't fly in
    }
    hot = !!ptr;

    p += (tp - p) * k;
    hi += (th - hi) * k;
    hx += (tx - hx) * k;
    hy += (ty - hy) * k;

    mark.style.setProperty("--p", (p * 100).toFixed(2) + "%");
    mark.style.setProperty("--hx", hx.toFixed(1) + "px");
    mark.style.setProperty("--hy", hy.toFixed(1) + "px");
    mark.style.setProperty("--hi", hi.toFixed(3));

    if (ptr) {
      for (const g of gilt) {
        const b = g.getBoundingClientRect();
        g.style.setProperty("--mx", ptr.x - b.left + "px");
        g.style.setProperty("--my", ptr.y - b.top + "px");
      }
      lit = true;
      glow.style.setProperty("--px", ptr.x + "px");
      glow.style.setProperty("--py", ptr.y + "px");
    } else if (lit) {
      for (const g of gilt) { g.style.removeProperty("--mx"); g.style.removeProperty("--my"); }
      lit = false;
    }

    raf = requestAnimationFrame(frame);
  }

  function kick() {
    if (raf) return;
    last = performance.now();
    raf = requestAnimationFrame(frame);
  }

  /* ---------- cover page ---------- */

  // The CSS already handles this on its own: the cover page is a <label> for the checkbox
  // above it, and a CSS animation fades it out after six seconds. All the script does is
  // tidy the element away and start the app at the moment it goes. That means a frame that
  // never runs scripts (sandboxed without "allow-scripts", an <img>, a preview pane) still
  // gets through — and so does one where this script dies part way down.
  const gate = $("gate");
  const gateBox = $("gate-open");
  let gateGone = false;

  function openGate() {
    if (gateGone || !gate) return;
    gateGone = true;
    gate.classList.add("gate-out");
    root.classList.remove("gated");
    setTimeout(() => {
      if (gate.parentNode) gate.parentNode.removeChild(gate);
      fill();
      route(); // a shared link like /#/html/0-fa opens now, not behind the cover
    }, 340);
  }

  if (gate) {
    // the click path is the label/checkbox; these just get there sooner, or another way
    if (gateBox) gateBox.addEventListener("change", openGate);
    addEventListener("keydown", openGate, true);
    addEventListener("wheel", openGate, { passive: true });
    setTimeout(openGate, 6000); // the CSS timer is the backstop, this keeps them in step
    let left = 6;
    const tick = setInterval(() => {
      const node = $("gate-left");
      if (!node || left <= 1 || gateGone) return;
      left -= 1;
      node.textContent = String(left);
    }, 1000);
    gateTick = tick;
    try { if (window.top !== window.self) openGate(); } catch (e) { openGate(); } // embedded: no cover
  }
  let gateTick = 0;

  /* ---------- shield: open pyrite inside an about:blank tab ---------- */

  const shield = $("shield");
  function cloak() {
    const w = window.open("about:blank", "_blank");
    if (!w) { flash("allow pop-ups to open in about:blank"); return; }
    const d = w.document;
    d.title = document.title;
    const icon = document.querySelector('link[rel~="icon"][sizes="32x32"]') || document.querySelector('link[rel~="icon"]');
    if (icon) {
      const l = d.createElement("link");
      l.rel = "icon";
      l.href = icon.href; // resolved to an absolute address, so it works from about:blank
      d.head.appendChild(l);
    }
    d.documentElement.style.background = "#050505";
    d.body.style.cssText = "margin:0;height:100vh;overflow:hidden;background:#050505";
    const f = d.createElement("iframe");
    f.src = location.href.split("#")[0]; // the cover page is skipped when pyrite is embedded
    f.style.cssText = "display:block;width:100%;height:100%;border:0";
    f.setAttribute("allow", "autoplay; fullscreen; gamepad; clipboard-write; accelerometer; gyroscope; microphone; camera");
    f.setAttribute("allowfullscreen", "");
    d.body.appendChild(f);
  }
  shield.addEventListener("click", cloak);

  kick();
  try {
    apply();
    // the grid is live, so the no-scripts note is no longer needed
    const nojs = document.querySelector(".nojs");
    if (nojs && nojs.parentNode) nojs.parentNode.removeChild(nojs);
  } catch (e) { /* the cover page still opens through the CSS */ }
  route(); // a shared link like /#/html/0-fa opens straight into the game (after the cover page)
})();
//
